draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  // Six
  ctx.beginPath();
  ctx.arc(W / 2 - 100, H / 2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2 - 100, H / 2, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 100, H / 2 + 20);
  ctx.lineTo(W / 2 - 100, H / 2 + 50);
  ctx.stroke();
  // Six movement
  ctx.beginPath();
  ctx.arc(W / 2 - 100 + Math.sin(t) * 10, H / 2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2 - 100 + Math.sin(t) * 10, H / 2, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 100 + Math.sin(t) * 10, H / 2 + 20);
  ctx.lineTo(W / 2 - 100 + Math.sin(t) * 10, H / 2 + 50);
  ctx.stroke();
  // Four
  ctx.beginPath();
  ctx.rect(W / 2 - 30, H / 2 - 50, 20, 100);
  ctx.stroke();
  // Four movement
  ctx.beginPath();
  ctx.rect(W / 2 - 30 + Math.cos(t) * 5, H / 2 - 50, 20, 100);
  ctx.stroke();
  // Four dot
  ctx.beginPath();
  ctx.arc(W / 2 - 30 + 10, H / 2 - 30, 5, 0, 2 * Math.PI);
  ctx.fill();
  // Four dot movement
  ctx.beginPath();
  ctx.arc(W / 2 - 30 + 10 + Math.cos(t) * 5, H / 2 - 30, 5, 0, 2 * Math.PI);
  ctx.fill();
  // Sixty Four
  ctx.font = '20px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 2;
  ctx.strokeText('64', W / 2 + 50, H / 2 - 20);
  ctx.fillText('64', W / 2 + 50, H / 2 - 20);
  ctx.restore();
}
